{"command": "cd /tmp/hwpx_work && python3 -c "
import zipfile, re

# Comprehensive verification
print('=== Final HWPX Verification ===\n')

with zipfile.ZipFile('/root/safety_audit_brief_final.hwpx', 'r') as zf:
    # List all files
    print('Files in archive:')
    for name in zf.namelist():
        print(f'  {name}')
    print()

    # Check each section XML
    for name in zf.namelist():
        if name.endswith('.xml'):
            content = zf.read(name).decode('utf-8')
            print(f'--- Checking {name} ---')

            # 1. No leftover placeholders
            placeholders = re.findall(r'\{\{[^}]+\}\}', content)
            if placeholders:
                print(f'  ❌ FAIL: Leftover placeholders: {placeholders}')
            else:
                print('  ✓ No leftover placeholders')

            # 2. Risk tier with severity note
            if 'High (즉시조치)' in content:
                print('  ✓ Risk tier with severity note: High (즉시조치)')

            # 3. Date format YYYY.MM.DD
            if re.search(r'\d{4}\.\d{2}\.\d{2}', content):
                print('  ✓ Date format YYYY.MM.DD present')

            # 4. No YYYY-MM-DD format
            if re.search(r'\d{4}-\d{2}-\d{2}', content):
                print('  ❌ FAIL: YYYY-MM-DD date format still present')
            else:
                print('  ✓ No YYYY-MM-DD date format')

            # 5. No lineSegArray elements
            if 'lineSegArray' in content:
                print('  ❌ FAIL: lineSegArray elements still present')
            else:
                print('  ✓ No lineSegArray elements')

            print()

print('\n=== All Verifications Complete ===')
